SEMI = frozenset({'ADI', 'ALAB', 'AMAT', 'AMD', 'ARM', 'ASML', 'AVGO', 'GFS', 'INTC', 'KLAC', 'LRCX', 'MCHP', 'MPWR', 'MRVL', 'MU', 'NVDA', 'NXPI', 'ON', 'Q', 'QCOM', 'QRVO', 'SWKS', 'TER', 'TXN'})
TOP5 = frozenset({"Information Technology", "Communication Services", "Financials", "Health Care", "Consumer Discretionary"})


def _timeline(current, changes):
    """[(生效日, 該日起的名單)] 升序；同一天多筆異動只留全部套用後的名單。"""
    s, out = set(current), []
    for eff, add, drop in sorted(changes, reverse=True):
        if not out or out[-1][0] != eff:
            out.append((eff, frozenset(s)))
        s.discard(add)
        if drop:
            s.add(drop)
    out.append(("", frozenset(s)))
    out.sort(key=lambda x: x[0])
    return out, [e for e, _ in out]

_SP = _timeline(SP500_CURRENT, SP500_CHANGES)
_NDX = _timeline(NDX_CURRENT, NDX_CHANGES)


def _on(tl, d_iso):
    return tl[0][bisect.bisect_right(tl[1], d_iso) - 1][1]


def groups_on(d_iso: str) -> dict:
    """當天三組：qqq＝Nasdaq-100、voo5＝S&P 500 中前五大板塊、soxx＝S&P 500 ∪ Nasdaq-100 中的半導體股。"""
    sp, nd = _on(_SP, d_iso), _on(_NDX, d_iso)
    return {"qqq": nd, "voo5": frozenset(t for t in sp if SECTOR.get(t) in TOP5), "soxx": frozenset(t for t in sp | nd if t in SEMI)}


def all_tickers() -> set:
    """2012-06 起曾是成分股的所有代號（回補下載用）。"""
    s = set(SP500_CURRENT) | set(NDX_CURRENT)
    for _, add, drop in SP500_CHANGES + NDX_CHANGES:
        s |= {t for t in (add, drop) if t}
    return s
